    [8519] = { title = "Небесна родина", desc = "Отримай усіх чотирьох небесних улюбленців." },
    [8520] = { title = "Вогонь!", desc = "Стрибни на 6 розжарених повзучих мін, а потім здолай Залізного Колоса в Облозі Оґриммару на звичайній складності чи вище." },
    [8521] = { title = "Прибори свою пиху", desc = "Здолай Ша Пихи в Облозі Оґриммару на звичайній складності чи вище так, щоб жоден гравець не отримав Пиху від Проявів Пихи, доки Норушен живий." },
    [8527] = { title = "Велетенський динозавр проти мегаслимака", desc = "Відчини Тричі Замкнену Клітку під час бою з Током Кровожерливим в Облозі Оґриммару на звичайній складності чи вище, а потім дозволь її мешканцю поласувати трупом Тока, коли здолаєш цей бій." },
    [8528] = { title = "Довгий пас", desc = "Передай Тавро Муки щонайменше 5 різним гравцям на загальній відстані 200 ярдів чи більше за одну фазу Відчайдушних Заходів, а потім здолай Полеглих Захисників в Облозі Оґриммару на звичайній складності чи вище." },
    [8529] = { title = "Навхрест", desc = "Заверши бій Здобич Пандарії в Облозі Оґриммару на звичайній складності чи вище так, щоб жоден учасник рейду не здолав і мантида, і ворога-моґу." },
    [8530] = { title = "Безсмертний авангард", desc = "Здолай Галакраса так, щоб жоден дружній НІП не загинув у бою, в Облозі Оґриммару на звичайній складності чи вище." },
    [8531] = { title = "Тепер обранці — ми", desc = "Здолай Обранців, прийнявши подобу трьох різних Обранців, в Облозі Оґриммару на звичайній складності чи вище." },
    [8532] = { title = "Ви не пройдете", desc = "Здолай Амальгаму Зіпсуття так, щоб з нею не злилося жодне вивільнене зіпсуття, в Облозі Оґриммару на звичайній складності чи вище." },
    [8533] = { title = "Ордос", desc = "Здолай Ордоса, бога вогню яунголів, на вершині Позачасового Острова." },
    [8535] = { title = "Небесний виклик", desc = "Пройди випробування всіх чотирьох Небожителів, здолавши кожного з них у бою на Позачасовому Острові." },
    [8536] = { title = "Годі сліз", desc = "Здолай Іммерсея, убивши 10 Сліз Долини, в Облозі Оґриммару на звичайній складності чи вище." },
    [8537] = { title = "Страйк!", desc = "Убий 18 Призвідців війни Кор'крону одним Залізним Зорельотом, а потім здолай Гарроша в Облозі Оґриммару на звичайній складності чи вище." },
    [8538] = { title = "Безмежний потенціал", desc = "Перетвори Зіпсованого Черепокола на Зіпсовану Амальгаму, а потім здолай Малкорока в Облозі Оґриммару на звичайній складності чи вище." },
