    [16430] = { title = "І гавкає, і кусає", desc = "Перемож Деревопащу після того, як кожного гравця було поглинуто щонайменше раз, у Виярку Папоротешкурів на міфічній складності." },
    [16431] = { title = "Проти стихій", desc = "Перемож кожного з елементальних володарів під час подій перед запуском Dragonflight." },
    [16432] = { title = "Готовий до рейдів VIII", desc = "Перемож Майстра кузні Ґорека, не зазнавши влучань Кузняного шторму, Кузняного вогню, Палаючих вивержень, Палаючої егіди іншого гравця чи останнього удару Розпечених замахів у Нелтарусі на міфічній складності." },
    [16434] = { title = "Зайди до мене після уроку", desc = "Перемож Вексамуса так, щоб жоден гравець не поглинув арканних сфер, в Академії Алґет'ара на міфічній складності." },
    [16438] = { title = "Знання... збережено?", desc = "Перемож Чарґата, Згубу Луски, спаливши менш ніж 15 книг у Нелтарусі на міфічній складності." },
