    [16445] = { title = "Ось де собака заморожений", desc = "Перемож Телаша Сірокрила після того, як 12 разів застосуєш Крижаного Спустошувача на Крижаний кристал, щоб створити Дуже крижаний кристал, у Лазуровому Сховищі на міфічній складності." },
    [16446] = { title = "А це доволі мило!", desc = "Зроби знімок камерою S.E.L.F.I.E. з усіма птахами (і птахоспостерігачами!) Драконових Островів, наведеними нижче." },
