    [41613] = { title = "Час голосувати! Милий чи страшний?", desc = "Здолай Лум'ітара після того, як усі вирішать, від нього /cower (зіщулитися) чи його /cuddle (пригорнути), перш ніж почати бій у манакузні Омега на складності «Нормальна» або вище." },
    [41614] = { title = "Мати всіх істерик", desc = "Здолай Душезв'язувачку Наазіндрі після того, як знищиш усі Маленькі звільнені душі в манакузні Омега на складності «Нормальна» або вище." },
